pub enum PlanningConfig {
    Git {
        #[serde(default = "default_planning_remote")]
        remote: String,
        /// Omit for this user's stable personal ref.
        #[serde(default)]
        shared: Option<String>,
    },
    Linear {},
}

if changed {
    let mut edits = Vec::new();
    if let Some(value) = &patch.name {
        edits.push(Edit::TaskTitle(Some(value.clone())));
    }
    if let Some(value) = &patch.description {
        edits.push(Edit::TaskDescription(Some(value.clone())));
    }
    if let Some(value) = &patch.assignee {
        edits.push(Edit::TaskAssignee(value.clone()));
    }
    planning_write::local(&tx, PlanningKind::Task, id.as_str(), &edits)?;
}

if let Some(value) = selection.task {
    let value = value.trim();
    let task = crate::ops::task::resolve_task(store, repo, value).await?;
